import re
SSN = re.compile(r"\b\d{3}-\d{2}-\d{4}\b")
CARD = re.compile(r"\b(?:\d[ -]?){13,16}\b")

def redact(text):
    # Illustrative only. In production use a maintained detection framework.
    return CARD.sub("[card]", SSN.sub("[ssn]", text))

