g-loop.code:
def normalize(s): return " ".join(s.lower().split())

def is_loop(assistant_msgs, user_msgs):
    a = [normalize(m) for m in assistant_msgs[-2:]]
    u = [normalize(m) for m in user_msgs[-2:]]
    return (len(a) == 2 and a[0] == a[1]) or (len(u) == 2 and u[0] == u[1])

